import{_ as o,o as e,c as t,a5 as r}from"./chunks/framework.BEZBAInb.js";const u=JSON.parse('{"title":"Konado のインストール","description":"","frontmatter":{"title":"Konado のインストール","order":1},"headers":[],"relativePath":"ja/2.4/tutorial/install.md","filePath":"ja/2.4/tutorial/install.md","lastUpdated":1788455378000}'),l={name:"ja/2.4/tutorial/install.md"};function i(n,a,d,s,h,c){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="konado-のインストール" tabindex="-1">Konado のインストール <a class="header-anchor" href="#konado-のインストール" aria-label="Permalink to &quot;Konado のインストール&quot;">​</a></h1><h2 id="必要環境" tabindex="-1">必要環境 <a class="header-anchor" href="#必要環境" aria-label="Permalink to &quot;必要環境&quot;">​</a></h2><p><strong>Godot 4.6 以上</strong>が必要です。</p><p>以下の Godot バージョンは開発者によってテスト済みで、正常に使用できます。</p><ul><li>4.6</li><li>4.5.1</li><li>4.5</li></ul><h3 id="プラグインのダウンロード" tabindex="-1">プラグインのダウンロード <a class="header-anchor" href="#プラグインのダウンロード" aria-label="Permalink to &quot;プラグインのダウンロード&quot;">​</a></h3><h4 id="安定版-推奨" tabindex="-1">安定版（推奨） <a class="header-anchor" href="#安定版-推奨" aria-label="Permalink to &quot;安定版（推奨）&quot;">​</a></h4><p><a href="https://github.com/godothub/konado/releases/latest" target="_blank" rel="noreferrer">Konado 最新リリースページ</a> にアクセスし、最新安定版のプラグイン ZIP パッケージをダウンロードしてください。安定版は十分に検証されており、安定性と信頼性が高いため、本番環境での第一候補です。</p><p>中国本土のユーザーのダウンロード体験を向上させるため、以下の最適化リンクからリソースを取得することを推奨します：<a href="https://atomgit.com/godothub/konado/releases" target="_blank" rel="noreferrer">Release リンク</a>。このリンクはダウンロード速度の改善に役立ちます。</p><h4 id="デイリービルド版-プレビュー版" tabindex="-1">デイリービルド版（プレビュー版） <a class="header-anchor" href="#デイリービルド版-プレビュー版" aria-label="Permalink to &quot;デイリービルド版（プレビュー版）&quot;">​</a></h4><p>デイリービルド版も提供しています。最新の開発機能を試したい場合は、<a href="https://github.com/godothub/konado/releases/" target="_blank" rel="noreferrer">Konado 全リリースページ</a> にアクセスし、タイトルに <code>Konado Daily Build</code> と記載されたバージョンを探してダウンロードしてください。</p><p>開発者であり、最新の開発機能を試したい場合は、デイリービルド版をダウンロードし、使用中に見つけた問題を Issues へ報告してください。</p><blockquote><p>Caution：デイリービルド版は最新開発機能の試用のみを目的としています。十分にテストされていない新機能を含むため、未修正の Bug が存在する可能性があります。<strong>本番環境では使用しないでください</strong>。実際の需要に応じて慎重に選択してください。</p></blockquote><h2 id="インストール手順" tabindex="-1">インストール手順 <a class="header-anchor" href="#インストール手順" aria-label="Permalink to &quot;インストール手順&quot;">​</a></h2><ol><li>Godot プロジェクトディレクトリにプラグインフォルダー <code>addons</code> を作成します</li><li>release のプラグイン zip パッケージをダウンロードします</li><li><code>addons</code> ディレクトリへ展開します</li><li>Godot のプロジェクト設定でプラグインを有効にし、現在のプロジェクトを再読み込みします</li></ol><blockquote><p>Tip: 初回インストールおよびプラグイン有効化時にいくつかのエラーが表示される場合があります。無視してプロジェクトを再読み込みすれば問題ありません。</p></blockquote><h2 id="開発チームからのメッセージ" tabindex="-1">開発チームからのメッセージ <a class="header-anchor" href="#開発チームからのメッセージ" aria-label="Permalink to &quot;開発チームからのメッセージ&quot;">​</a></h2><p>Konado プラグインのインストールが完了しました。正式に制作を始める前に、ひとつメッセージを共有します。</p><blockquote><p>「どんな業界においても、想像力に少しの知恵が加われば、それは無敵の武器になる。」</p><p>—— フィリップ・K・ディック（Philip K. Dick）<br> 『マイノリティ・リポート』（<em>Minority Report</em>，1956）</p></blockquote><p>想像力とより良いものを追求する姿勢を持ち続け、創作の道でさらに多くの可能性を探求できますように。</p>',20)])])}const b=o(l,[["render",i]]);export{u as __pageData,b as default};
